# Rank policies
# ---------------------------------------------------------------------------

class FifoPolicy:
    kind = "fifo"

    def __init__(self, spec):
        self.time = 0

    def attempt(self, flow, length, flow_size):
        self.time += 1
        return self.time

    def service(self, rank):
        pass

    def update_weight(self, flow, weight):
        pass

    def certificate(self):
        return {"kind": "fifo", "time": self.time}

    def snapshot(self):
        return (self.time,)

    def restore(self, data):
        self.time = data[0]


class SpPolicy:
    kind = "sp"

    def __init__(self, spec):
        levels = spec.get("levels", [])
        self.levels = sorted((int(flow), int(level))
                             for flow, level in levels)
        self.lookup = dict(self.levels)

    def attempt(self, flow, length, flow_size):
        return self.lookup[flow]

    def service(self, rank):
        pass

    def update_weight(self, flow, weight):
        pass

    def certificate(self):
        return {"kind": "sp",
                "levels": [[flow, level] for flow, level in self.levels]}

    def snapshot(self):
        return None

    def restore(self, data):
        pass


class SffPolicy:
    kind = "sff"

    def __init__(self, spec):
        pass

    def attempt(self, flow, length, flow_size):
        return flow_size

    def service(self, rank):
        pass

    def update_weight(self, flow, weight):
        pass

    def certificate(self):
        return {"kind": "sff"}

    def snapshot(self):
        return None

    def restore(self, data):
        pass


class WfqPolicy:
    kind = "wfq"

    def __init__(self, spec):
        weights = sorted((int(flow), int(weight))
                         for flow, weight in spec.get("weights", []))
        self.flow_ids = [flow for flow, _ in weights]
        self.weights = None
        self.finish = None
        for flow, weight in weights:
            self.weights = flow_set(self.weights, flow, weight)
            self.finish = flow_set(self.finish, flow, 0)
        self.virtual_time = 0

    def attempt(self, flow, length, flow_size):
        weight = flow_get(self.weights, flow)
        old_finish = flow_get(self.finish, flow)
        base = old_finish if old_finish > self.virtual_time \
            else self.virtual_time
        new_finish = base + (length * 1048576 + weight - 1) // weight
        self.finish = flow_set(self.finish, flow, new_finish)
        return new_finish

    def service(self, rank):
        if rank > self.virtual_time:
            self.virtual_time = rank

    def update_weight(self, flow, weight):
        self.weights = flow_set(self.weights, flow, weight)

    def certificate(self):
        return {
            "kind": "wfq",
            "virtual_time": self.virtual_time,
            "weights": [[flow, flow_get(self.weights, flow)]
                        for flow in self.flow_ids],
            "finish": [[flow, flow_get(self.finish, flow)]
                       for flow in self.flow_ids],
        }

    def snapshot(self):
        return (self.virtual_time, self.weights, self.finish)

    def restore(self, data):
        self.virtual_time, self.weights, self.finish = data


def make_policy(spec):
    kind = spec.get("kind")
    if kind == "fifo":
        return FifoPolicy(spec)
    if kind == "sp":
        return SpPolicy(spec)
    if kind == "sff":
        return SffPolicy(spec)
    if kind == "wfq":
        return WfqPolicy(spec)
    raise ValueError("unknown policy")


